package com.digitalhealth.service;
import com.digitalhealth.dto.ConsentDTO;import com.digitalhealth.model.*;import com.digitalhealth.repository.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class ConsentService{private final ConsentRepository consents;private final WorkerRepository workers;public ConsentService(ConsentRepository c,WorkerRepository w){consents=c;workers=w;}public ConsentDTO grant(Long workerId,ConsentDTO d){Worker w=workers.findById(workerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Worker not found"));Consent c=new Consent();c.setWorker(w);c.setProvider(d.getProvider());c.setGrantedDate(d.getGrantedDate());c.setExpiryDate(d.getExpiryDate());c.setPurpose(d.getPurpose());c.setStatus("ACTIVE");return dto(consents.save(c));}public List<ConsentDTO> list(Long id){return consents.findByWorkerIdOrderByGrantedDateDesc(id).stream().map(this::dto).toList();}public ConsentDTO revoke(Long workerId,Long id){Consent c=consents.findById(id).filter(x->x.getWorker().getId().equals(workerId)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Consent not found"));c.setStatus("REVOKED");return dto(consents.save(c));}private ConsentDTO dto(Consent c){ConsentDTO d=new ConsentDTO();d.setId(c.getId());d.setProvider(c.getProvider());d.setGrantedDate(c.getGrantedDate());d.setExpiryDate(c.getExpiryDate());d.setPurpose(c.getPurpose());d.setStatus(c.getStatus());return d;}}
